	if n.ResolvedProvider.Provider.Type == "" {
		panic("GetProvider used with uninitialized provider configuration address")
	}
	metaProvider := ctx.Provider(n.ResolvedProvider)
	if metaProvider == nil {
		return nil, diags.Append(fmt.Errorf("provider %s not initialized", n.ResolvedProvider))
	}
	metaProviderSchema, metaSchemaErr := ctx.ProviderSchema(n.ResolvedProvider)
	if metaSchemaErr != nil {
		return nil, diags.Append(fmt.Errorf("failed to read schema for provider %s: %w", n.ResolvedProvider, metaSchemaErr))
	}
