				} else {
					leftPath := leftMark.Path
					rightPath := rightMark.Path
					pathLen := len(leftPath)
					if len(rightPath) != pathLen {
						marksDiffer = true
						if len(rightPath) < pathLen {
							pathLen = len(rightPath)
						}
					}
					for stepIdx := 0; stepIdx < pathLen; stepIdx++ {
						switch leftStep := leftPath[stepIdx].(type) {
						case cty.GetAttrStep:
							rightStep, ok := rightPath[stepIdx].(cty.GetAttrStep)
							if !ok || leftStep.Name != rightStep.Name {
								marksDiffer = true
							}
						case cty.IndexStep:
							rightStep, ok := rightPath[stepIdx].(cty.IndexStep)
							if !ok || !leftStep.Key.RawEquals(rightStep.Key) {
								marksDiffer = true
							}
						default:
							marksDiffer = true
						}
						if marksDiffer {
							break
						}
					}
				}
				if marksDiffer {
					break
				}
			}
		}
		if marksDiffer {
			// Copy the previous state, changing only the value
			newState := &states.ResourceInstanceObject{
				CreateBeforeDestroy: state.CreateBeforeDestroy,
				Dependencies:        state.Dependencies,
				Private:             state.Private,
				Status:              state.Status,
				Value:               change.After,
			}
			return newState, diags
		}
	}

	var resp providers.ApplyResourceChangeResponse
	if n.override != nil {
		// As with the planning stage, we only need to worry about computed
		// values the first time the object is created. Otherwise, we're happy
		// to just apply whatever the user asked for.
		if change.Action == plans.Create {
			override, overrideDiags := mocking.ApplyComputedValuesForResource(unmarkedAfter, mocking.MockedData{
				Value: n.override.Values,
				Range: n.override.ValuesRange,
			}, schema)
			resp = providers.ApplyResourceChangeResponse{
				NewState:    override,
				Diagnostics: overrideDiags,
			}
		} else {
			resp = providers.ApplyResourceChangeResponse{
				NewState: unmarkedAfter,
			}
		}
	} else {
		resp = provider.ApplyResourceChange(providers.ApplyResourceChangeRequest{
			TypeName:       n.Addr.Resource.Resource.Type,
			PriorState:     unmarkedBefore,
			Config:         unmarkedConfigVal,
			PlannedState:   unmarkedAfter,
			PlannedPrivate: change.Private,
			ProviderMeta:   metaConfigVal,
		})
	}
	applyDiags := resp.Diagnostics
	if applyConfig != nil {
		applyDiags = applyDiags.InConfigBody(applyConfig.Config, n.Addr.String())
	}
	diags = diags.Append(applyDiags)

